int x = 1, y = 2;

// Standard assignment
x = 10;

// Compound assignment
y *= 3; // y is 6
x &= 1; // Bitwise AND assignment

// Chaining (RTL associative, returns lvalue ref)
x = y += 4; // y is 10, x is 10

class Container {
    int* ptr = nullptr;
public:
    // Required: Modifiable lvalue on left
    Container& operator=(const Container& other) { /* ... */ return *this; }

    // Modern C++: Move Assignment
    Container& operator=(Container&& other) noexcept {
        if (this != &other) {
            delete[] ptr;
            ptr = other.ptr;
            other.ptr = nullptr;
        }
        return *this; // Must return lvalue reference
    }
};
